      lazymatch type of HRT with rtbl _ _ ?RT =>
        let kb := constr:(kst_ctor ++ fkn (EVar 33) SF ++ fkn (EVar 32) DF) in
        let kf := eval vm_compute in (kfix stops pc (HLib.srs sr_id RT) kb) in
        let r := eval vm_compute in
          (sym_exec asegs fuel true stops (SCR dirs [] []) (SS pc (HLib.srs sr_id RT) [] ((kst_ctor ++ kf) ++ fkn (EVar 33) SF ++ fkn (EVar 32) DF) 60) []) in
        lazymatch r with
        | (?SSr, ?scs, ?scr') =>
          let RT' := eval vm_compute in (wtbl (wbound Wc) (s_regs SSr)) in
          let ks1 := eval vm_compute in (nkeys (EVar 33) (s_log SSr) SF) in
          let ks2 := eval vm_compute in (nkeys (EVar 32) (s_log SSr) DF) in
          eapply (dk_run Wc (EVar 33) (EVar 32) spz ds (-8192) 0 0 DS_SIZE eq_refl eq_refl HB1c HB2c HW1c HW2c WDJc Pw Pw_step
                    Q R F pc fc m ro RT SF DF [] (kst_ctor ++ kf) fuel stops (SCR dirs [] []) 60%N SSr scs scr' RT' ks1 ks2);
          [ assumption | exact HRT | vm_compute; reflexivity | exact HSF | exact HDF | exact HP | exact HMI
          | vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
          | apply (wr_keys_stk m); [exact (proj1 HP) | vm_compute; reflexivity] | apply (wr_keys_ds m); [exact (proj1 HP) | vm_compute; reflexivity]
          | unfold know_ok; apply Forall_app; split; [apply kst_ok; exact (proj1 HP) | ]
          | vm_cast_no_check (@eq_refl _ (SSr, scs, scr'))
          | | vm_compute; reflexivity | vm_compute; reflexivity | ]
        end
      end end end
    end.
  Ltac scu HspE :=
    first [ scw HspE
          | cbn [sc_denot]; evw; wnorm HspE; cbn [edenot];
            first [ rewrite br_ltu by lia; apply Z.ltb_ge; lia
                  | rewrite br_ltu by lia; apply Z.ltb_lt; lia
                  | rewrite br_eq by lia; apply Z.eqb_neq; lia
                  | rewrite w_and by lia; change 7 with (Z.ones 3); rewrite Z.land_ones by lia;
                    rewrite br_ne by (Z.div_mod_to_equations; lia); apply negb_false_iff, Z.eqb_eq; Z.div_mod_to_equations; lia ] ].
  Ltac scs_all HspE := repeat (apply Forall_cons; [scu HspE |]); apply Forall_nil.

  Lemma cut5 : forall R m, rfull R -> rtbl Wc R RT5 -> ftbl Wc spz m SF5 -> ftbl Wc ds m DF5 -> Pw m -> mem_inv asegs m ->
    evt asegs ctor_P (MS R F (Z_to_bv 64 DSC_R5) fc None m (seg_rom asegs)).
Proof.
  intros R5 m5 RF5 HRT5 HSF5 HDF5 HP5 HMI5.
  pose (spv := bv_unsigned sp).
  assert (HspE : sp = Z_to_bv 64 spv) by (symmetry; apply Z_to_bv_bv_unsigned).
  pose proof sp_range as (SR1 & SR2 & SR3 & SR4).
  pose proof aceil_facts as (AC1 & AC2 & AC3 & AC4).
  pose proof DSO as (DO1 & DO2 & DO3).
  pose proof PPO as (PO1 & PO2 & PO3).
  pose proof S1O as (QO1 & QO2 & QO3).
  pose proof S2O as (UO1 & UO2 & UO3).
  pose proof PCO as (KO1 & KO2 & KO3).
  unfold AIMG_TOP, AAPP_HI, ALOWSH_LO, AHI_LO, DS_SIZE, CT_STACK in DO1, DO2, DO3, PO1, PO2, PO3, QO1, QO2, QO3, UO1, UO2, UO3, KO1, KO2, KO3, SR3, SR4.
  dkrunD HRT5 HSF5 HDF5 HP5 HMI5 600%nat [AASAN_MEMCPY] [false].
  { dkf HP5 HspE. }
  { scs_all HspE. }
  intros R6 m6 RF6 HRT6 HSF6 HDF6 HP6 HMI6 MU6 WM6.
  cbn [s_pc].
  tnorm HSF6. tnorm HDF6.
  dregs HRT6 HspE G10 G11 G12 G2 G1.
  pose proof (src_ppos m6 HP6) as [SRC6 LEN6].
  dcall_mc spv RF6 HRT6 HSF6 HDF6 HP6 HMI6 G10 G11 G12 G2 G1 (u64s pos) SRC6 LEN6.
  intros R6' m6' RF6' HRT6' HSF6' HDF6' HP6' HMI6' RES6.
  rewrite ?sub_off in HDF6'.
  clear RES6.
  tnorm HDF6'. tnorm HRT6'. dstk spv HSF6'.
  dkrunD HRT6' HSF6' HDF6' HP6' HMI6' 600%nat [AASAN_MEMCPY] (@nil bool).
  { dkf HP6' HspE. }
  { scs_all HspE. }
  intros R7 m7 RF7 HRT7 HSF7 HDF7 HP7 HMI7 MU7 WM7.
  cbn [s_pc].
  tnorm HSF7. tnorm HDF7.
  dregs HRT7 HspE G10 G11 G12 G2 G1.
  pose proof (src_pstr m7 HP7) as [SRC7 LEN7].
  dcall_mc spv RF7 HRT7 HSF7 HDF7 HP7 HMI7 G10 G11 G12 G2 G1 (cells_bytes [C2 (Z_to_bv 64 0); CB 22 j1]) SRC7 LEN7.
  intros R7' m7' RF7' HRT7' HSF7' HDF7' HP7' HMI7' RES7.
  rewrite ?sub_off in HDF7'.
  pose proof (ftbl_prefix Wc ds m7' _ 24 2 (ELit 0) (j1 ++ []) RES7 ltac:(lia)) as HZ7.
  rewrite ?sub_off in HZ7.
  pose proof (ftbl_app _ _ _ _ _ HDF7' HZ7) as HDF7''. clear HDF7' HZ7.
  tnorm HDF7''. tnorm HRT7'. dstk spv HSF7'.
  dkrunD HRT7' HSF7' HDF7'' HP7' HMI7' 600%nat [AASAN_MEMCPY] [false; false].
  { dkf HP7' HspE. }
  { scs_all HspE. }
  intros R8 m8 RF8 HRT8 HSF8 HDF8 HP8 HMI8 MU8 WM8.
  cbn [s_pc].
  tnorm HSF8. tnorm HDF8.
  dregs HRT8 HspE G10 G11 G12 G2 G1.
  pose proof (src_pstr2 m8 HP8) as [SRC8 LEN8].
  dcall_mc spv RF8 HRT8 HSF8 HDF8 HP8 HMI8 G10 G11 G12 G2 G1 (cells_bytes [C2 (Z_to_bv 64 0); CB 22 j2]) SRC8 LEN8.
  intros R8' m8' RF8' HRT8' HSF8' HDF8' HP8' HMI8' RES8.
  rewrite ?sub_off in HDF8'.
  pose proof (ftbl_prefix Wc ds m8' _ 24 2 (ELit 0) (j2 ++ []) RES8 ltac:(lia)) as HZ8.
  rewrite ?sub_off in HZ8.
  pose proof (ftbl_app _ _ _ _ _ HDF8' HZ8) as HDF8''. clear HDF8' HZ8.
  tnorm HDF8''. tnorm HRT8'. dstk spv HSF8'.
  dkrunD HRT8' HSF8' HDF8'' HP8' HMI8' 600%nat [DSC_RET] (@nil bool).
  { dkf HP8' HspE. }
  { scs_all HspE. }
  intros R9 m9 RF9 HRT9 HSF9 HDF9 HP9 HMI9 MU9 WM9.
  cbn [s_pc].
  tnorm HDF9.
  rget HRT9 (1%bv : reg) HspE K1. rget HRT9 (2%bv : reg) HspE K2. rget HRT9 (3%bv : reg) HspE K3. rget HRT9 (4%bv : reg) HspE K4.
  rget HRT9 (8%bv : reg) HspE K8. rget HRT9 (9%bv : reg) HspE K9. rget HRT9 (18%bv : reg) HspE K18. rget HRT9 (19%bv : reg) HspE K19.
  rget HRT9 (20%bv : reg) HspE K20. rget HRT9 (21%bv : reg) HspE K21. rget HRT9 (22%bv : reg) HspE K22. rget HRT9 (23%bv : reg) HspE K23.
  rget HRT9 (24%bv : reg) HspE K24. rget HRT9 (25%bv : reg) HspE K25. rget HRT9 (26%bv : reg) HspE K26. rget HRT9 (27%bv : reg) HspE K27.
  rewrite <- HspE in K2.
  rewrite (MS_full_eq R9 F _ fc m9 _ RF9).
  rewrite K1, K2, K3, K4, K8, K9, K18, K19, K20, K21, K22, K23, K24, K25, K26, K27.
  apply ctor_ret_ok.
  unfold LbB_DCtorK.ctor_P.
  eexists _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, m9.
  split; [reflexivity|]. split; [exact HMI9|]. split; [exact HP9|].
  apply (ds_rep_end m9 HP9). unfold ftbl in HDF9 |- *. apply Forall_forall. intros x Hx.
  apply (proj1 (Forall_forall _ _) HDF9). apply fent_in_In.
  lazymatch type of HDF9 with Forall _ ?t =>
    exact (proj1 (forallb_forall (fun y => fent_in y t) DF9) ltac:(vm_compute; reflexivity) x Hx) end.
Qed.
End CtorR5.
